/* From Uiverse.io by Na3ar-17  - Tags: simple, tailwind, tailwindcss */
.__UIV_SCOPE__ .container * {
  padding: 0;
  margin: 0;
}

.__UIV_SCOPE__ .card {
  width: 363px;
  height: 130px;
  background-color: #1e293b;
  border-radius: 10px;
  display: grid;
  grid-template-rows: 40px 1fr;
}

.__UIV_SCOPE__ .card .header {
  display: flex;
  align-items: center;
  position: relative;
}

.__UIV_SCOPE__ .card .header .title {
  color: #7dd3fc;
  font-size: 13px;
  padding: 2px 12px;
}

.__UIV_SCOPE__ .card .header .copy {
  position: absolute;
  top: 61%;
  right: 1px;
  transform: translate(-50%, -50%);
  color: rgb(100, 116, 139);
  cursor: pointer;
  transition: all 0.3s ease;
  z-index: 100;
}

.__UIV_SCOPE__ .card .header .copy:hover {
  color: rgb(148, 163, 184);
}

.__UIV_SCOPE__ .card .header::before {
  content: "";
  position: absolute;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
  border: 1px solid #64748b4d;
  right: 1px;
  bottom: 0;
  background-color: #33415580;
  width: 282px;
  height: 33px;
  z-index: 100;
}

.__UIV_SCOPE__ .card .header::after {
  content: "";
  position: absolute;
  width: 22%;
  height: 1px;
  background-color: #7dd3fc;
  bottom: 0;
}

.__UIV_SCOPE__ .card .footer {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  padding-left: 10px;
}

.__UIV_SCOPE__ .card .footer .code {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .card .footer .code .icon {
  color: rgb(244, 114, 182);
  padding-top: 3px;
}

.__UIV_SCOPE__ .card .footer .code .text {
  padding-left: 3px;
  color: #f8fafc;
}
